/**
 * Smitten: the `smitten` engine module.
 *
 * Not part of upstream LÖVE. Most of the module is Lua (lua/*.lua), embedded
 * by build.py as smitten_lua.h. This file registers those files in
 * package.preload as "smitten.<name>", exposes the native functions as
 * "smitten.native", and returns the result of lua/init.lua.
 *
 * Licensed under the zlib license, like LÖVE (see love/license.txt).
 **/

#include "common/runtime.h"
#include "wrap_Smitten.h"

#include <cstring>
#include <string>

#include "smitten_lua.h" // generated by build.py

namespace love
{
namespace smitten
{

static int loadEmbedded(lua_State *L, const SmittenLuaFile &file)
{
	std::string chunkname = std::string("=[smitten \"") + file.name + ".lua\"]";
	return luaL_loadbuffer(L, (const char *) file.data, file.size, chunkname.c_str());
}

} // smitten
} // love

extern "C" int luaopen_smitten(lua_State *L)
{
	using namespace love::smitten;

	lua_getglobal(L, "package");
	lua_getfield(L, -1, "preload");
	lua_getfield(L, -2, "loaded");
	// Stack: package, preload, loaded

	lua_newtable(L);
	luaL_register(L, nullptr, native_functions);
	lua_setfield(L, -2, "smitten.native");

	const SmittenLuaFile *init = nullptr;
	for (const SmittenLuaFile *f = smitten_lua_files; f->name != nullptr; f++)
	{
		if (strcmp(f->name, "init") == 0)
		{
			init = f;
			continue;
		}
		if (loadEmbedded(L, *f) != 0)
			return lua_error(L);
		lua_setfield(L, -3, (std::string("smitten.") + f->name).c_str());
	}
	lua_pop(L, 3);

	if (init == nullptr)
		return luaL_error(L, "smitten: init.lua is missing from the build");
	if (loadEmbedded(L, *init) != 0)
		return lua_error(L);
	lua_call(L, 0, 1);
	return 1;
}
